<?php
require __DIR__.'/../includes/bootstrap.php';
if(!$user)redirect('../login.php');
try{
 if($_SERVER['REQUEST_METHOD']!=='POST')throw new RuntimeException('Open the print slip from the requisition details page.');check_csrf();$r=get_request((int)($_POST['id']??0));if(!in_array($r['status'],['Approved','Dispatched','Returned','Completed']))throw new RuntimeException('Only approved requisitions can be printed.');
 $approvals=all("SELECT a.*,u.full_name FROM approvals a JOIN users u ON u.id=a.user_id WHERE requisition_id=? AND decision='Approved' ORDER BY a.id",[$r['id']]);$sign=[];foreach($approvals as $a)$sign[$a['stage']]=$a;
 $m=one('SELECT m.*,u.full_name checked_name FROM vehicle_movements m LEFT JOIN users u ON u.id=m.checked_by WHERE requisition_id=?',[$r['id']]);run('INSERT INTO print_logs(requisition_id,user_id,created_at) VALUES(?,?,?)',[$r['id'],$user['id'],date('Y-m-d H:i:s')]);audit('Requisition print opened',$r['reference']);
}catch(Throwable $e){http_response_code(403);exit(e($e instanceof PDOException?'Unable to load print record.':$e->getMessage()));}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=e($r['reference'])?> · Requisition slip</title><link rel="stylesheet" href="../assets/css/print.css"></head><body><div class="no-print"><button onclick="window.print()">Print / Save as PDF</button><a href="../index.php?page=request&id=<?=$r['id']?>">Back to requisition</a></div><main class="requisition-slip"><header><p>Republic of the Philippines</p><h2><?=e(setting('organization'))?></h2><h1>VEHICLE REQUISITION SLIP</h1><div class="print-meta"><span>Reference: <strong><?=e($r['reference'])?></strong></span><span>Date: <?=shortdate($r['created_at'])?></span></div></header><h3>REQUESTING PERSONNEL</h3><table><tr><th>Requested by</th><td><?=e($r['requester_name'])?></td><th>Designation</th><td><?=e($r['position'])?></td></tr><tr><th>Office / division</th><td colspan="3"><?=e($r['office_name'])?></td></tr><tr><th>Passengers</th><td colspan="3"><?=nl2br(e($r['passengers']))?></td></tr></table><h3>VEHICLE & JOURNEY DETAILS</h3><table><?php foreach(['Requested vehicle type'=>$r['vehicle_type'],'Assigned vehicle'=>$r['model'].' · '.$r['plate'],'Assigned driver'=>$r['driver_name'],'Date & time of use'=>shortdate($r['start_datetime'],'F j, Y — g:i A'),'Estimated return'=>shortdate($r['end_datetime'],'F j, Y — g:i A'),'Destination'=>$r['destination'],'Purpose'=>$r['purpose'],'Fuel requirement'=>($r['fuel_allocation']?'With fuel allocation':'Without fuel allocation').' · '.(float)$r['fuel_quantity'].' liters requested','Fuel remarks'=>$r['fuel_remarks']?:'—'] as $label=>$value):?><tr><th><?=e($label)?></th><td><?=nl2br(e($value))?></td></tr><?php endforeach?></table><h3>APPROVAL</h3><div class="signature-grid"><?php foreach(['Supervisor'=>'supervisor_signatory','Administrative'=>'admin_signatory'] as $stage=>$key):?><div><p>Approved by:</p><div class="signature-space"></div><strong><?=e($sign[$stage]['full_name']??'')?></strong><p><?=e(setting($key))?></p><small>Date approved: <?=isset($sign[$stage])?shortdate($sign[$stage]['created_at'],'M j, Y g:i A'):'____________'?></small><p class="remarks"><?=e($sign[$stage]['remarks']??'')?></p></div><?php endforeach?></div><h3>OFFICE RECORD — DISPATCH & RETURN</h3><table><?php foreach(['Actual release time'=>$m['departure']??'','Actual return time'=>$m['return_time']??'','Odometer out'=>$m?number_format($m['odometer_out']).' km':'','Odometer in'=>isset($m['odometer_in'])?number_format($m['odometer_in']).' km':'','Distance travelled'=>isset($m['odometer_in'])?number_format($m['odometer_in']-$m['odometer_out']).' km':'','Vehicle condition'=>$m['condition_text']??'','Checked by'=>$m['checked_name']??'','Return remarks / incidents'=>$m['remarks']??''] as $label=>$value):?><tr><th><?=e($label)?></th><td><?=e($value?:'________________________________________________________________')?></td></tr><?php endforeach?></table><footer>Generated <?=date('F j, Y g:i A')?> · <?=e($r['reference'])?> · Status: <?=e($r['status'])?></footer></main></body></html>
